FILES['exercises/models.py'] = 'import re\nfrom django.db import models\n\n\nclass MuscleGroup(models.Model):\n    name = models.CharField(max_length=100, unique=True)\n\n    class Meta:\n        ordering = [\'name\']\n        verbose_name = "Grupa miesniowa"\n        verbose_name_plural = "Grupy miesniowe"\n\n    def __str__(self):\n        return self.name\n\n\nclass Equipment(models.Model):\n    name = models.CharField(max_length=100, unique=True)\n\n    class Meta:\n        ordering = [\'name\']\n        verbose_name = "Sprzet"\n        verbose_name_plural = "Sprzet"\n\n    def __str__(self):\n        return self.name\n\n\nclass Exercise(models.Model):\n    DIFFICULTY_CHOICES = [\n        (\'easy\', \'Latwy\'),\n        (\'medium\', \'Sredni\'),\n        (\'hard\', \'Trudny\'),\n    ]\n\n    name = models.CharField(max_length=200, verbose_name="Nazwa")\n    description = models.TextField(verbose_name="Opis")\n    video_url = models.URLField(blank=True, null=True, verbose_name="Link do video", help_text="Link np. do YouTube")\n    muscle_groups = models.ManyToManyField(MuscleGroup, related_name=\'exercises\', verbose_name="Grupy miesniowe")\n    difficulty = models.CharField(max_length=10, choices=DIFFICULTY_CHOICES, verbose_name="Poziom trudnosci")\n    equipment = models.ManyToManyField(Equipment, blank=True, related_name=\'exercises\', verbose_name="Potrzebny sprzet")\n    contraindications = models.TextField(blank=True, verbose_name="Przeciwwskazania")\n\n    parent_exercise = models.ForeignKey(\n        \'self\', null=True, blank=True,\n        on_delete=models.SET_NULL,\n        related_name=\'variants\',\n        verbose_name="Wariant cwiczenia"\n    )\n    variant_name = models.CharField(\n        max_length=100, blank=True,\n        verbose_name="Nazwa wariantu",\n        help_text=\'np. "Zaawansowany", "Z pilka", "Dla szczeniaka"\'\n    )\n\n    is_active = models.BooleanField(default=True, verbose_name="Aktywne")\n\n    created_at = models.DateTimeField(auto_now_add=True)\n    updated_at = models.DateTimeField(auto_now=True)\n\n    class Meta:\n        ordering = [\'-created_at\']\n        verbose_name = "Cwiczenie"\n        verbose_name_plural = "Cwiczenia"\n\n    def __str__(self):\n        return self.name\n\n    def get_youtube_embed_url(self):\n        """Zwraca URL do embedowania video YouTube, albo None jesli to nie YouTube/niepoprawny link"""\n        if not self.video_url:\n            return None\n\n        patterns = [\n            r\'(?:youtube\\.com\\/watch\\?v=)([^&\\n?#]+)\',\n            r\'(?:youtu\\.be\\/)([^&\\n?#]+)\',\n            r\'(?:youtube\\.com\\/embed\\/)([^&\\n?#]+)\',\n        ]\n        for pattern in patterns:\n            match = re.search(pattern, self.video_url)\n            if match:\n                return f\'https://www.youtube.com/embed/{match.group(1)}\'\n        return None\n\n    def active_variants(self):\n        """Lista aktywnych wariantow tego cwiczenia (jesli to cwiczenie \'glowne\')"""\n        return self.variants.filter(is_active=True).order_by(\'created_at\')\n\n    def get_root(self):\n        """Zwraca cwiczenie \'glowne\' - jesli to wariant, zwraca jego rodzica; jesli samo jest glowne, zwraca siebie"""\n        return self.parent_exercise if self.parent_exercise else self\n\n    def get_cover_image(self):\n        """Zwraca zdjecie oznaczone jako okladka, albo pierwsze dostepne zdjecie (wg kolejnosci)"""\n        cover = self.images.filter(is_cover=True).first()\n        return cover or self.images.order_by(\'order\', \'pk\').first()\n\n\nclass ExerciseImage(models.Model):\n    exercise = models.ForeignKey(Exercise, related_name=\'images\', on_delete=models.CASCADE)\n    image = models.ImageField(upload_to=\'exercises/\')\n    is_cover = models.BooleanField(default=False, verbose_name="Zdjecie okladkowe")\n    order = models.PositiveIntegerField(default=0, verbose_name="Kolejnosc")\n\n    MAX_DIMENSION = 1600\n\n    class Meta:\n        ordering = [\'order\', \'pk\']\n        verbose_name = "Zdjecie cwiczenia"\n        verbose_name_plural = "Zdjecia cwiczen"\n\n    def __str__(self):\n        return f"Zdjecie dla {self.exercise.name}"\n\n    def save(self, *args, **kwargs):\n        super().save(*args, **kwargs)\n        self._resize_if_needed()\n\n    def _resize_if_needed(self):\n        """Automatycznie skaluje i kompresuje zdjecie, jesli jest wieksze niz MAX_DIMENSION.\n        Dzialanie \'pod maska\' - bez wplywu na UI, oszczedza miejsce i czas wczytywania."""\n        try:\n            from PIL import Image as PILImage\n            if not self.image or not self.image.name:\n                return\n            path = self.image.path\n            with PILImage.open(path) as img:\n                width, height = img.size\n                if width <= self.MAX_DIMENSION and height <= self.MAX_DIMENSION:\n                    return\n\n                img = img.convert(\'RGB\') if img.mode in (\'RGBA\', \'P\') else img\n                img.thumbnail((self.MAX_DIMENSION, self.MAX_DIMENSION), PILImage.LANCZOS)\n\n                save_kwargs = {\'optimize\': True}\n                fmt = (img.format or \'JPEG\')\n                if path.lower().endswith((\'.jpg\', \'.jpeg\')):\n                    save_kwargs[\'quality\'] = 85\n                    fmt = \'JPEG\'\n                img.save(path, format=fmt, **save_kwargs)\n        except Exception:\n            pass\n'
FILES['exercises/admin.py'] = 'from django.contrib import admin\nfrom .models import MuscleGroup, Equipment, Exercise, ExerciseImage\n\n\nclass ExerciseImageInline(admin.TabularInline):\n    model = ExerciseImage\n    extra = 1\n    fields = (\'image\', \'is_cover\', \'order\')\n\n\n@admin.register(MuscleGroup)\nclass MuscleGroupAdmin(admin.ModelAdmin):\n    list_display = (\'name\',)\n    search_fields = (\'name\',)\n\n\n@admin.register(Equipment)\nclass EquipmentAdmin(admin.ModelAdmin):\n    list_display = (\'name\',)\n    search_fields = (\'name\',)\n\n\n@admin.register(Exercise)\nclass ExerciseAdmin(admin.ModelAdmin):\n    list_display = (\'name\', \'variant_name\', \'parent_exercise\', \'difficulty\', \'is_active\', \'created_at\')\n    list_filter = (\'difficulty\', \'is_active\', \'muscle_groups\', \'equipment\')\n    search_fields = (\'name\', \'description\', \'variant_name\')\n    filter_horizontal = (\'muscle_groups\', \'equipment\')\n    inlines = [ExerciseImageInline]\n    actions = [\'make_active\', \'make_archived\']\n    list_per_page = 50\n    date_hierarchy = \'created_at\'\n\n    def make_active(self, request, queryset):\n        updated = queryset.update(is_active=True)\n        self.message_user(request, f"Przywrocono {updated} cwiczen (ustawiono jako aktywne).")\n    make_active.short_description = "Przywroc zaznaczone (ustaw jako aktywne)"\n\n    def make_archived(self, request, queryset):\n        updated = queryset.update(is_active=False)\n        self.message_user(request, f"Zarchiwizowano {updated} cwiczen.")\n    make_archived.short_description = "Zarchiwizuj zaznaczone"\n'
FILES['exercises/views.py'] = 'import json\n\nfrom django.shortcuts import render, redirect, get_object_or_404\nfrom django.contrib import messages\nfrom django.contrib.auth.decorators import login_required\nfrom django.db.models import Q, Case, When, IntegerField\nfrom django.core.paginator import Paginator\nfrom django.http import JsonResponse\nfrom .models import MuscleGroup, Equipment, Exercise, ExerciseImage\nfrom .forms import MuscleGroupForm, EquipmentForm, ExerciseForm, ExerciseImageUploadForm\n\nEXERCISES_PER_PAGE = 25\n\nSORT_OPTIONS = [\n    (\'newest\', \'Najnowsze\'),\n    (\'oldest\', \'Najstarsze\'),\n    (\'name_asc\', \'Nazwa A-Z\'),\n    (\'name_desc\', \'Nazwa Z-A\'),\n    (\'difficulty\', \'Poziom trudnosci\'),\n]\n\n\n# ============ MUSCLE GROUP ============\n\n@login_required\ndef muscle_group_list(request):\n    muscle_groups = MuscleGroup.objects.all()\n    return render(request, \'exercises/muscle_group_list.html\', {\n        \'muscle_groups\': muscle_groups\n    })\n\n\n@login_required\ndef muscle_group_create(request):\n    if request.method == \'POST\':\n        form = MuscleGroupForm(request.POST)\n        if form.is_valid():\n            form.save()\n            messages.success(request, \'Grupa miesniowa zostala dodana.\')\n            return redirect(\'muscle_group_list\')\n    else:\n        form = MuscleGroupForm()\n    return render(request, \'exercises/muscle_group_form.html\', {\n        \'form\': form,\n        \'title\': \'Dodaj grupe miesniowa\'\n    })\n\n\n@login_required\ndef muscle_group_update(request, pk):\n    muscle_group = get_object_or_404(MuscleGroup, pk=pk)\n    if request.method == \'POST\':\n        form = MuscleGroupForm(request.POST, instance=muscle_group)\n        if form.is_valid():\n            form.save()\n            messages.success(request, \'Grupa miesniowa zostala zaktualizowana.\')\n            return redirect(\'muscle_group_list\')\n    else:\n        form = MuscleGroupForm(instance=muscle_group)\n    return render(request, \'exercises/muscle_group_form.html\', {\n        \'form\': form,\n        \'title\': \'Edytuj grupe miesniowa\'\n    })\n\n\n@login_required\ndef muscle_group_delete(request, pk):\n    muscle_group = get_object_or_404(MuscleGroup, pk=pk)\n    if request.method == \'POST\':\n        muscle_group.delete()\n        messages.success(request, \'Grupa miesniowa zostala usunieta.\')\n        return redirect(\'muscle_group_list\')\n    return render(request, \'exercises/muscle_group_confirm_delete.html\', {\n        \'muscle_group\': muscle_group\n    })\n\n\n# ============ EQUIPMENT ============\n\n@login_required\ndef equipment_list(request):\n    equipment = Equipment.objects.all()\n    return render(request, \'exercises/equipment_list.html\', {\n        \'equipment\': equipment\n    })\n\n\n@login_required\ndef equipment_create(request):\n    if request.method == \'POST\':\n        form = EquipmentForm(request.POST)\n        if form.is_valid():\n            form.save()\n            messages.success(request, \'Sprzet zostal dodany.\')\n            return redirect(\'equipment_list\')\n    else:\n        form = EquipmentForm()\n    return render(request, \'exercises/equipment_form.html\', {\n        \'form\': form,\n        \'title\': \'Dodaj sprzet\'\n    })\n\n\n@login_required\ndef equipment_update(request, pk):\n    equipment = get_object_or_404(Equipment, pk=pk)\n    if request.method == \'POST\':\n        form = EquipmentForm(request.POST, instance=equipment)\n        if form.is_valid():\n            form.save()\n            messages.success(request, \'Sprzet zostal zaktualizowany.\')\n            return redirect(\'equipment_list\')\n    else:\n        form = EquipmentForm(instance=equipment)\n    return render(request, \'exercises/equipment_form.html\', {\n        \'form\': form,\n        \'title\': \'Edytuj sprzet\'\n    })\n\n\n@login_required\ndef equipment_delete(request, pk):\n    equipment = get_object_or_404(Equipment, pk=pk)\n    if request.method == \'POST\':\n        equipment.delete()\n        messages.success(request, \'Sprzet zostal usuniety.\')\n        return redirect(\'equipment_list\')\n    return render(request, \'exercises/equipment_confirm_delete.html\', {\n        \'equipment\': equipment\n    })\n\n\n# ============ EXERCISE ============\n\n@login_required\ndef exercise_list(request):\n    exercises = Exercise.objects.filter(\n        parent_exercise__isnull=True, is_active=True\n    ).prefetch_related(\'muscle_groups\', \'equipment\', \'images\', \'variants\')\n\n    search_query = request.GET.get(\'q\', \'\').strip()\n    muscle_group_filter = request.GET.get(\'muscle_group\')\n    difficulty_filter = request.GET.get(\'difficulty\')\n    sort = request.GET.get(\'sort\', \'newest\')\n\n    if search_query:\n        exercises = exercises.filter(\n            Q(name__icontains=search_query) | Q(description__icontains=search_query) |\n            Q(variants__name__icontains=search_query) | Q(variants__description__icontains=search_query)\n        )\n\n    if muscle_group_filter:\n        exercises = exercises.filter(\n            Q(muscle_groups__id=muscle_group_filter) | Q(variants__muscle_groups__id=muscle_group_filter)\n        )\n    if difficulty_filter:\n        exercises = exercises.filter(\n            Q(difficulty=difficulty_filter) | Q(variants__difficulty=difficulty_filter)\n        )\n\n    exercises = exercises.distinct()\n\n    if sort == \'oldest\':\n        exercises = exercises.order_by(\'created_at\')\n    elif sort == \'name_asc\':\n        exercises = exercises.order_by(\'name\')\n    elif sort == \'name_desc\':\n        exercises = exercises.order_by(\'-name\')\n    elif sort == \'difficulty\':\n        order = Case(\n            When(difficulty=\'easy\', then=0),\n            When(difficulty=\'medium\', then=1),\n            When(difficulty=\'hard\', then=2),\n            output_field=IntegerField()\n        )\n        exercises = exercises.annotate(diff_order=order).order_by(\'diff_order\')\n    else:\n        exercises = exercises.order_by(\'-created_at\')\n        sort = \'newest\'\n\n    paginator = Paginator(exercises, EXERCISES_PER_PAGE)\n    page_number = request.GET.get(\'page\')\n    page_obj = paginator.get_page(page_number)\n\n    get_copy = request.GET.copy()\n    get_copy.pop(\'page\', None)\n    querystring = get_copy.urlencode()\n\n    stats_qs = Exercise.objects.filter(is_active=True)\n    stats = {\n        \'total\': stats_qs.count(),\n        \'main\': stats_qs.filter(parent_exercise__isnull=True).count(),\n        \'variants\': stats_qs.filter(parent_exercise__isnull=False).count(),\n        \'easy\': stats_qs.filter(difficulty=\'easy\').count(),\n        \'medium\': stats_qs.filter(difficulty=\'medium\').count(),\n        \'hard\': stats_qs.filter(difficulty=\'hard\').count(),\n    }\n\n    return render(request, \'exercises/exercise_list.html\', {\n        \'page_obj\': page_obj,\n        \'muscle_groups\': MuscleGroup.objects.all(),\n        \'difficulty_choices\': Exercise.DIFFICULTY_CHOICES,\n        \'sort_options\': SORT_OPTIONS,\n        \'selected_muscle_group\': muscle_group_filter,\n        \'selected_difficulty\': difficulty_filter,\n        \'selected_sort\': sort,\n        \'search_query\': search_query,\n        \'querystring\': querystring,\n        \'stats\': stats,\n    })\n\n\n@login_required\ndef exercise_detail(request, pk):\n    exercise = get_object_or_404(Exercise, pk=pk)\n    return render(request, \'exercises/exercise_detail.html\', {\n        \'exercise\': exercise\n    })\n\n\ndef _create_images_with_order(exercise, images):\n    """Tworzy obiekty ExerciseImage z poprawna, narastajaca kolejnoscia."""\n    start_order = exercise.images.count()\n    created = []\n    for idx, img in enumerate(images):\n        obj = ExerciseImage.objects.create(exercise=exercise, image=img, order=start_order + idx)\n        created.append(obj)\n    return created\n\n\n@login_required\ndef exercise_create(request):\n    if request.method == \'POST\':\n        form = ExerciseForm(request.POST)\n        image_form = ExerciseImageUploadForm(request.POST, request.FILES)\n\n        if form.is_valid() and image_form.is_valid():\n            exercise = form.save()\n\n            images = request.FILES.getlist(\'images\')\n            _create_images_with_order(exercise, images)\n\n            if images and not exercise.images.filter(is_cover=True).exists():\n                first_img = exercise.images.order_by(\'order\', \'pk\').first()\n                if first_img:\n                    first_img.is_cover = True\n                    first_img.save()\n\n            messages.success(request, \'Cwiczenie zostalo dodane.\')\n            return redirect(\'exercise_detail\', pk=exercise.pk)\n    else:\n        form = ExerciseForm()\n        image_form = ExerciseImageUploadForm()\n\n    return render(request, \'exercises/exercise_form.html\', {\n        \'form\': form,\n        \'image_form\': image_form,\n        \'title\': \'Dodaj cwiczenie\'\n    })\n\n\n@login_required\ndef exercise_update(request, pk):\n    exercise = get_object_or_404(Exercise, pk=pk)\n\n    if request.method == \'POST\':\n        form = ExerciseForm(request.POST, instance=exercise)\n        image_form = ExerciseImageUploadForm(request.POST, request.FILES)\n\n        if form.is_valid() and image_form.is_valid():\n            form.save()\n\n            images = request.FILES.getlist(\'images\')\n            _create_images_with_order(exercise, images)\n\n            cover_id = request.POST.get(\'cover_image\')\n            if cover_id:\n                exercise.images.update(is_cover=False)\n                ExerciseImage.objects.filter(pk=cover_id, exercise=exercise).update(is_cover=True)\n\n            if not exercise.images.filter(is_cover=True).exists():\n                first_img = exercise.images.order_by(\'order\', \'pk\').first()\n                if first_img:\n                    first_img.is_cover = True\n                    first_img.save()\n\n            messages.success(request, \'Cwiczenie zostalo zaktualizowane.\')\n            return redirect(\'exercise_detail\', pk=exercise.pk)\n    else:\n        form = ExerciseForm(instance=exercise)\n        image_form = ExerciseImageUploadForm()\n\n    return render(request, \'exercises/exercise_form.html\', {\n        \'form\': form,\n        \'image_form\': image_form,\n        \'title\': \'Edytuj cwiczenie\',\n        \'exercise\': exercise,\n    })\n\n\n@login_required\ndef exercise_delete(request, pk):\n    """Soft delete - przeniesienie do archiwum"""\n    exercise = get_object_or_404(Exercise, pk=pk)\n    active_variants_count = exercise.variants.filter(is_active=True).count()\n\n    if request.method == \'POST\':\n        exercise.is_active = False\n        exercise.save()\n        messages.success(request, \'Cwiczenie zostalo przeniesione do archiwum.\')\n        return redirect(\'exercise_list\')\n\n    return render(request, \'exercises/exercise_confirm_delete.html\', {\n        \'exercise\': exercise,\n        \'active_variants_count\': active_variants_count,\n    })\n\n\n@login_required\ndef exercise_duplicate(request, pk):\n    original = get_object_or_404(Exercise, pk=pk)\n\n    new_parent = original.parent_exercise if original.parent_exercise else original\n\n    new_exercise = Exercise.objects.create(\n        name=f"{original.name} (kopia)",\n        description=original.description,\n        video_url=original.video_url,\n        difficulty=original.difficulty,\n        contraindications=original.contraindications,\n        parent_exercise=new_parent,\n        variant_name=original.variant_name or "Nowy wariant",\n        is_active=True,\n    )\n    new_exercise.muscle_groups.set(original.muscle_groups.all())\n    new_exercise.equipment.set(original.equipment.all())\n\n    messages.success(request, \'Cwiczenie zostalo zduplikowane jako wariant. Zdjecia nie zostaly skopiowane - dodaj je osobno.\')\n    return redirect(\'exercise_update\', pk=new_exercise.pk)\n\n\n@login_required\ndef exercise_archived_list(request):\n    exercises = Exercise.objects.filter(is_active=False).order_by(\'-updated_at\')\n    return render(request, \'exercises/exercise_archived_list.html\', {\n        \'exercises\': exercises\n    })\n\n\n@login_required\ndef exercise_restore(request, pk):\n    exercise = get_object_or_404(Exercise, pk=pk, is_active=False)\n    if request.method == \'POST\':\n        exercise.is_active = True\n        exercise.save()\n        messages.success(request, \'Cwiczenie zostalo przywrocone.\')\n    return redirect(\'exercise_archived_list\')\n\n\n@login_required\ndef exercise_delete_permanent(request, pk):\n    exercise = get_object_or_404(Exercise, pk=pk, is_active=False)\n    if request.method == \'POST\':\n        exercise.delete()\n        messages.success(request, \'Cwiczenie zostalo usuniete na zawsze.\')\n    return redirect(\'exercise_archived_list\')\n\n\n@login_required\ndef exercise_image_delete(request, pk):\n    """Usuniecie pojedynczego zdjecia z galerii cwiczenia"""\n    image = get_object_or_404(ExerciseImage, pk=pk)\n    exercise_pk = image.exercise.pk\n    if request.method == \'POST\':\n        image.delete()\n        messages.success(request, \'Zdjecie zostalo usuniete.\')\n    return redirect(\'exercise_update\', pk=exercise_pk)\n\n\n@login_required\ndef exercise_image_reorder(request, pk):\n    """Endpoint AJAX do zapisywania nowej kolejnosci zdjec (drag&drop)."""\n    exercise = get_object_or_404(Exercise, pk=pk)\n    if request.method != \'POST\':\n        return JsonResponse({\'status\': \'error\', \'message\': \'Metoda niedozwolona.\'}, status=405)\n\n    try:\n        payload = json.loads(request.body.decode(\'utf-8\'))\n        order_list = payload.get(\'order\', [])\n    except (ValueError, UnicodeDecodeError):\n        return JsonResponse({\'status\': \'error\', \'message\': \'Nieprawidlowe dane.\'}, status=400)\n\n    for idx, image_id in enumerate(order_list):\n        ExerciseImage.objects.filter(pk=image_id, exercise=exercise).update(order=idx)\n\n    return JsonResponse({\'status\': \'ok\'})\n'
FILES['exercises/urls.py'] = "from django.urls import path\nfrom . import views\n\nurlpatterns = [\n    # Cwiczenia\n    path('', views.exercise_list, name='exercise_list'),\n    path('exercises/add/', views.exercise_create, name='exercise_create'),\n    path('exercises/archived/', views.exercise_archived_list, name='exercise_archived_list'),\n    path('exercises/<int:pk>/', views.exercise_detail, name='exercise_detail'),\n    path('exercises/<int:pk>/edit/', views.exercise_update, name='exercise_update'),\n    path('exercises/<int:pk>/delete/', views.exercise_delete, name='exercise_delete'),\n    path('exercises/<int:pk>/duplicate/', views.exercise_duplicate, name='exercise_duplicate'),\n    path('exercises/<int:pk>/restore/', views.exercise_restore, name='exercise_restore'),\n    path('exercises/<int:pk>/delete-permanent/', views.exercise_delete_permanent, name='exercise_delete_permanent'),\n    path('exercises/<int:pk>/images/reorder/', views.exercise_image_reorder, name='exercise_image_reorder'),\n    path('exercises/image/<int:pk>/delete/', views.exercise_image_delete, name='exercise_image_delete'),\n\n    # Grupy miesniowe\n    path('muscle-groups/', views.muscle_group_list, name='muscle_group_list'),\n    path('muscle-groups/add/', views.muscle_group_create, name='muscle_group_create'),\n    path('muscle-groups/<int:pk>/edit/', views.muscle_group_update, name='muscle_group_update'),\n    path('muscle-groups/<int:pk>/delete/', views.muscle_group_delete, name='muscle_group_delete'),\n\n    # Sprzet\n    path('equipment/', views.equipment_list, name='equipment_list'),\n    path('equipment/add/', views.equipment_create, name='equipment_create'),\n    path('equipment/<int:pk>/edit/', views.equipment_update, name='equipment_update'),\n    path('equipment/<int:pk>/delete/', views.equipment_delete, name='equipment_delete'),\n]\n"
FILES['templates/base.html'] = '<!DOCTYPE html>\n<html lang="pl">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>{% block title %}Dog Fitness{% endblock %}</title>\n\n    <link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css" rel="stylesheet">\n    <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.css">\n    <link rel="preconnect" href="https://fonts.googleapis.com">\n    <link href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700&display=swap" rel="stylesheet">\n\n    {% load static %}\n    <link rel="stylesheet" href="{% static \'css/style.css\' %}">\n</head>\n<body>\n    <nav class="navbar navbar-expand-lg navbar-custom">\n        <div class="container">\n            <a class="navbar-brand" href="{% url \'exercise_list\' %}">\n                <i class="bi bi-activity"></i> Dog Fitness\n            </a>\n            <button class="navbar-toggler" type="button" data-bs-toggle="collapse" data-bs-target="#navbarNav">\n                <span class="navbar-toggler-icon"></span>\n            </button>\n            <div class="collapse navbar-collapse" id="navbarNav">\n                <div class="navbar-nav ms-auto align-items-lg-center">\n                    {% if user.is_authenticated %}\n                        <a class="nav-link" href="{% url \'exercise_list\' %}"><i class="bi bi-list-ul"></i> Cwiczenia</a>\n                        <a class="nav-link" href="{% url \'muscle_group_list\' %}"><i class="bi bi-diagram-3"></i> Grupy miesniowe</a>\n                        <a class="nav-link" href="{% url \'equipment_list\' %}"><i class="bi bi-tools"></i> Sprzet</a>\n                        {% if user.is_staff %}\n                            <a class="nav-link" href="/admin/" target="_blank"><i class="bi bi-gear"></i> Panel admina</a>\n                        {% endif %}\n                        <span class="navbar-text-custom mx-3"><i class="bi bi-person-circle"></i> {{ user.username }}</span>\n                        <a class="nav-link" href="{% url \'logout\' %}"><i class="bi bi-box-arrow-right"></i> Wyloguj</a>\n                    {% endif %}\n                </div>\n            </div>\n        </div>\n    </nav>\n\n    <div class="container mt-4 mb-5">\n        {% if messages %}\n            {% for message in messages %}\n                <div class="alert alert-{{ message.tags|default:\'success\' }} d-flex align-items-center" role="alert">\n                    <i class="bi bi-check-circle-fill me-2"></i> {{ message }}\n                </div>\n            {% endfor %}\n        {% endif %}\n\n        {% block content %}{% endblock %}\n    </div>\n\n    <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/js/bootstrap.bundle.min.js"></script>\n    <script src="https://cdn.jsdelivr.net/npm/sortablejs@1.15.0/Sortable.min.js"></script>\n    <script>\n        function getCookie(name) {\n            let cookieValue = null;\n            if (document.cookie && document.cookie !== \'\') {\n                const cookies = document.cookie.split(\';\');\n                for (let i = 0; i < cookies.length; i++) {\n                    const cookie = cookies[i].trim();\n                    if (cookie.substring(0, name.length + 1) === (name + \'=\')) {\n                        cookieValue = decodeURIComponent(cookie.substring(name.length + 1));\n                        break;\n                    }\n                }\n            }\n            return cookieValue;\n        }\n\n        document.addEventListener(\'DOMContentLoaded\', function () {\n            document.querySelectorAll(\'.exercise-card\').forEach(function (card) {\n                const tabs = card.querySelectorAll(\'.variant-tab\');\n                tabs.forEach(function (tab) {\n                    tab.addEventListener(\'click\', function () {\n                        tabs.forEach(function (t) { t.classList.remove(\'active\'); });\n                        tab.classList.add(\'active\');\n\n                        card.querySelectorAll(\'.variant-content\').forEach(function (c) {\n                            c.style.display = \'none\';\n                        });\n                        const target = card.querySelector(\'#\' + tab.dataset.target);\n                        if (target) target.style.display = \'block\';\n\n                        const detailBtn = card.querySelector(\'.detail-link-btn\');\n                        if (detailBtn && tab.dataset.detailUrl) {\n                            detailBtn.href = tab.dataset.detailUrl;\n                        }\n                    });\n                });\n            });\n\n            document.querySelectorAll(\'.image-delete-form\').forEach(function (form) {\n                form.addEventListener(\'submit\', function (e) {\n                    if (!confirm(\'Czy na pewno chcesz usunac to zdjecie?\')) {\n                        e.preventDefault();\n                    }\n                });\n            });\n\n            const sortableEl = document.getElementById(\'existing-images-sortable\');\n            if (sortableEl && typeof Sortable !== \'undefined\') {\n                new Sortable(sortableEl, {\n                    animation: 150,\n                    ghostClass: \'sortable-ghost\',\n                    onEnd: function () {\n                        const ids = Array.from(sortableEl.children).map(function (el) {\n                            return el.dataset.id;\n                        });\n                        fetch(sortableEl.dataset.reorderUrl, {\n                            method: \'POST\',\n                            headers: {\n                                \'Content-Type\': \'application/json\',\n                                \'X-CSRFToken\': getCookie(\'csrftoken\'),\n                            },\n                            body: JSON.stringify({ order: ids })\n                        });\n                    }\n                });\n            }\n        });\n    </script>\n</body>\n</html>\n'
FILES['exercises/templates/exercises/exercise_form.html'] = '{% extends \'base.html\' %}\n{% block title %}{{ title }}{% endblock %}\n\n{% block content %}\n<h1 class="mb-4">{{ title }}</h1>\n\n<div class="form-card">\n    <form method="post" enctype="multipart/form-data">\n        {% csrf_token %}\n\n        {% if form.non_field_errors %}\n            <div class="alert alert-danger">{{ form.non_field_errors }}</div>\n        {% endif %}\n\n        <div class="mb-3">\n            <label class="form-label">Nazwa</label>\n            {{ form.name }}\n            {% if form.name.errors %}<div class="invalid-feedback-custom">{{ form.name.errors|first }}</div>{% endif %}\n        </div>\n\n        <div class="mb-3">\n            <label class="form-label">Opis</label>\n            {{ form.description }}\n            {% if form.description.errors %}<div class="invalid-feedback-custom">{{ form.description.errors|first }}</div>{% endif %}\n        </div>\n\n        <div class="mb-3">\n            <label class="form-label">Link do video (YouTube/Vimeo, opcjonalnie)</label>\n            {{ form.video_url }}\n            {% if form.video_url.errors %}<div class="invalid-feedback-custom">{{ form.video_url.errors|first }}</div>{% endif %}\n        </div>\n\n        <div class="mb-3">\n            <label class="form-label">Poziom trudnosci</label>\n            {{ form.difficulty }}\n        </div>\n\n        <div class="mb-3">\n            <label class="form-label">Grupy miesniowe</label>\n            <div class="checkbox-group">\n                {{ form.muscle_groups }}\n            </div>\n            {% if form.muscle_groups.errors %}<div class="invalid-feedback-custom">{{ form.muscle_groups.errors|first }}</div>{% endif %}\n            <small class="text-muted">Nie widzisz potrzebnej grupy? <a href="{% url \'muscle_group_create\' %}" target="_blank">Dodaj nowa</a></small>\n        </div>\n\n        <div class="mb-3">\n            <label class="form-label">Potrzebny sprzet</label>\n            <div class="checkbox-group">\n                {{ form.equipment }}\n            </div>\n            <small class="text-muted">Nie widzisz potrzebnego sprzetu? <a href="{% url \'equipment_create\' %}" target="_blank">Dodaj nowy</a></small>\n        </div>\n\n        <div class="mb-3">\n            <label class="form-label">Przeciwwskazania (opcjonalnie)</label>\n            {{ form.contraindications }}\n        </div>\n\n        <hr class="my-4">\n\n        <h5 class="mb-3"><i class="bi bi-diagram-2"></i> Warianty</h5>\n\n        <div class="mb-3">\n            <label class="form-label">To cwiczenie jest wariantem innego cwiczenia</label>\n            {{ form.parent_exercise }}\n            <small class="text-muted">Wybierz, jesli to np. trudniejsza/latwiejsza wersja istniejacego cwiczenia</small>\n        </div>\n\n        <div class="mb-3">\n            <label class="form-label">Nazwa wariantu (wymagana, jesli wybrano powyzej)</label>\n            {{ form.variant_name }}\n            {% if form.variant_name.errors %}<div class="invalid-feedback-custom">{{ form.variant_name.errors|first }}</div>{% endif %}\n        </div>\n\n        <hr class="my-4">\n\n        <div class="mb-3">\n            <label class="form-label"><i class="bi bi-images"></i> Dodaj zdjecia</label>\n            {{ image_form.images }}\n            {% if image_form.images.errors %}<div class="invalid-feedback-custom">{{ image_form.images.errors|first }}</div>{% endif %}\n            <small class="text-muted">Mozesz wybrac wiele plikow naraz (Ctrl+klik). Max 10 plikow, 5MB kazdy. Duze zdjecia zostana automatycznie zmniejszone.</small>\n        </div>\n\n        {% if exercise and exercise.images.all %}\n            <div class="mb-3">\n                <label class="form-label">\n                    Istniejace zdjecia - przeciagnij aby zmienic kolejnosc, wybierz okladke <i class="bi bi-star-fill" style="color:#D4AF37;"></i>\n                </label>\n                <div class="row" id="existing-images-sortable" data-reorder-url="{% url \'exercise_image_reorder\' exercise.pk %}">\n                    {% for img in exercise.images.all %}\n                    <div class="col-3 mb-2 text-center sortable-image-item" data-id="{{ img.pk }}">\n                        <div class="cover-select-wrapper">\n                            <img src="{{ img.image.url }}" class="img-fluid rounded mb-1" style="aspect-ratio: 1; object-fit: cover;" alt="Zdjecie">\n                            <label class="cover-radio-label">\n                                <input type="radio" name="cover_image" value="{{ img.pk }}" {% if img.is_cover %}checked{% endif %}>\n                                Okladka\n                            </label>\n                        </div>\n                        <span class="drag-handle-hint"><i class="bi bi-arrows-move"></i> przeciagnij</span>\n                        <form method="post" action="{% url \'exercise_image_delete\' img.pk %}" class="image-delete-form mt-1">\n                            {% csrf_token %}\n                            <button type="submit" class="btn btn-sm btn-outline-danger w-100">\n                                <i class="bi bi-trash"></i>\n                            </button>\n                        </form>\n                    </div>\n                    {% endfor %}\n                </div>\n            </div>\n        {% endif %}\n\n        <div class="mt-4">\n            <button type="submit" class="btn btn-primary"><i class="bi bi-check-lg"></i> Zapisz</button>\n            <a href="{% url \'exercise_list\' %}" class="btn btn-secondary">Anuluj</a>\n        </div>\n    </form>\n</div>\n{% endblock %}\n'


CSS_APPEND = '\n\n/* ============ DRAG & DROP ZDJEC (Runda 3) ============ */\n.sortable-image-item {\n    cursor: grab;\n    transition: transform 0.15s ease;\n}\n\n.sortable-image-item:active {\n    cursor: grabbing;\n}\n\n.sortable-ghost {\n    opacity: 0.4;\n}\n\n.drag-handle-hint {\n    font-size: 0.7rem;\n    color: #999;\n    display: block;\n    margin-top: 2px;\n}\n'


def main():
    print("=" * 70)
    print("DogFitness - _update2.py - RUNDA 3")
    print("=" * 70)

    if not os.path.exists(os.path.join(BASE_DIR, "manage.py")):
        print("!! UWAGA: nie znaleziono 'manage.py' w tym folderze.")
        print("   Uruchom ten skrypt z GLOWNEGO folderu projektu Django")
        print("   (tam gdzie jest plik manage.py).")
        answer = input("   Czy chcesz kontynuowac mimo to? (tak/nie): ").strip().lower()
        if answer not in ("tak", "t", "yes", "y"):
            print("Przerwano.")
            sys.exit(1)

    backed_up_any = False

    for rel_path, content in FILES.items():
        full_path = os.path.join(BASE_DIR, rel_path.replace("/", os.sep))
        dir_path = os.path.dirname(full_path)

        if not os.path.exists(dir_path):
            os.makedirs(dir_path, exist_ok=True)
            print(f"[+] Utworzono folder: {dir_path}")

        if os.path.exists(full_path):
            backup_target = os.path.join(BACKUP_DIR, rel_path.replace("/", os.sep))
            os.makedirs(os.path.dirname(backup_target), exist_ok=True)
            shutil.copy2(full_path, backup_target)
            backed_up_any = True

        with open(full_path, "w", encoding="utf-8") as f:
            f.write(content)
        print(f"[OK] Zapisano: {rel_path}")

    style_css_path = os.path.join(BASE_DIR, "static", "css", "style.css")
    if os.path.exists(style_css_path):
        with open(style_css_path, "r", encoding="utf-8") as f:
            existing_css = f.read()

        if "DRAG & DROP ZDJEC" not in existing_css:
            backup_target = os.path.join(BACKUP_DIR, "static", "css", "style.css")
            os.makedirs(os.path.dirname(backup_target), exist_ok=True)
            shutil.copy2(style_css_path, backup_target)
            backed_up_any = True

            with open(style_css_path, "a", encoding="utf-8") as f:
                f.write(CSS_APPEND)
            print("[OK] Dopisano fragment CSS (drag&drop) do: static/css/style.css")
        else:
            print("[--] Fragment CSS dla drag&drop juz istnieje w style.css - pominieto.")
    else:
        os.makedirs(os.path.dirname(style_css_path), exist_ok=True)
        with open(style_css_path, "w", encoding="utf-8") as f:
            f.write(CSS_APPEND)
        print("[OK] Nie znaleziono style.css - utworzono nowy z fragmentem drag&drop.")

    print("-" * 70)
    if backed_up_any:
        print(f"Kopie zapasowe nadpisanych plikow zapisano w:")
        print(f"  {BACKUP_DIR}")
    else:
        print("Nie bylo plikow do zbackupowania (wszystkie byly nowe).")

    print("-" * 70)
    print("GOTOWE! Nastepne kroki:")
    print("  1. python manage.py makemigrations   (nowe pole 'order' w ExerciseImage)")
    print("  2. python manage.py migrate")
    print("  3. python manage.py runserver")
    print("  4. Wejdz na /admin/ (zalogowany jako superuser) - sprawdz panel admina")
    print("  5. W edycji cwiczenia z wieloma zdjeciami - przetestuj przeciaganie zdjec")
    print("=" * 70)


if __name__ == "__main__":
    main()
